static size_t IfaceStemLen(const char* s) {
	size_t n = std::strlen(s);
	while (n > 0 && s[n-1] >= '0' && s[n-1] <= '9') --n;
	return n;
}

void* FindInterface(const char* v) {
	if (!v) return nullptr;
	size_t vn = IfaceStemLen(v);
	if (vn == 39 && std::strncmp(v, "STEAMPARENTALSETTINGS_INTERFACE_VERSION", 39) == 0) return SteamParentalSettings_ForVersion(v);
	if (vn == 36 && std::strncmp(v, "STEAMREMOTESTORAGE_INTERFACE_VERSION", 36) == 0) return SteamRemoteStorage_ForVersion(v);
	if (vn == 35 && std::strncmp(v, "STEAMHTMLSURFACE_INTERFACE_VERSION_", 35) == 0) return SteamHTMLSurface_ForVersion(v);
	if (vn == 34 && std::strncmp(v, "STEAMSCREENSHOTS_INTERFACE_VERSION", 34) == 0) return SteamScreenshots_ForVersion(v);
	if (vn == 33 && std::strncmp(v, "STEAMCONTROLLER_INTERFACE_VERSION", 33) == 0) return SteamController_ForVersion(v);
	if (vn == 33 && std::strncmp(v, "STEAMREMOTEPLAY_INTERFACE_VERSION", 33) == 0) return SteamRemotePlay_ForVersion(v);
	if (vn == 32 && std::strncmp(v, "STEAMUSERSTATS_INTERFACE_VERSION", 32) == 0) return SteamUserStats_ForVersion(v);
	if (vn == 28 && std::strncmp(v, "STEAMMUSIC_INTERFACE_VERSION", 28) == 0) return SteamMusic_ForVersion(v);
	if (vn == 27 && std::strncmp(v, "STEAMAPPS_INTERFACE_VERSION", 27) == 0) return SteamApps_ForVersion(v);
	if (vn == 27 && std::strncmp(v, "STEAMHTTP_INTERFACE_VERSION", 27) == 0) return SteamHTTP_ForVersion(v);
	if (vn == 26 && std::strncmp(v, "STEAMINVENTORY_INTERFACE_V", 26) == 0) return SteamInventory_ForVersion(v);
	if (vn == 26 && std::strncmp(v, "STEAMUGC_INTERFACE_VERSION", 26) == 0) return SteamUGC_ForVersion(v);
	if (vn == 25 && std::strncmp(v, "STEAMTIMELINE_INTERFACE_V", 25) == 0) return SteamTimeline_ForVersion(v);
	if (vn == 23 && std::strncmp(v, "SteamMatchMakingServers", 23) == 0) return SteamMatchmakingServers_ForVersion(v);
	if (vn == 23 && std::strncmp(v, "SteamNetworkingMessages", 23) == 0) return SteamNetworkingMessages_ForVersion(v);
	if (vn == 22 && std::strncmp(v, "STEAMVIDEO_INTERFACE_V", 22) == 0) return SteamVideo_ForVersion(v);
	if (vn == 22 && std::strncmp(v, "SteamNetworkingSockets", 22) == 0) return SteamNetworkingSockets_ForVersion(v);
	if (vn == 20 && std::strncmp(v, "SteamGameServerStats", 20) == 0) return SteamGameServerStats_ForVersion(v);
	if (vn == 20 && std::strncmp(v, "SteamNetworkingUtils", 20) == 0) return SteamNetworkingUtils_ForVersion(v);
	if (vn == 16 && std::strncmp(v, "SteamMatchMaking", 16) == 0) return SteamMatchmaking_ForVersion(v);
	if (vn == 15 && std::strncmp(v, "SteamController", 15) == 0) return SteamController_ForVersion(v);
	if (vn == 15 && std::strncmp(v, "SteamGameServer", 15) == 0) return SteamGameServer_ForVersion(v);
	if (vn == 15 && std::strncmp(v, "SteamNetworking", 15) == 0) return SteamNetworking_ForVersion(v);
	if (vn == 12 && std::strncmp(v, "SteamFriends", 12) == 0) return SteamFriends_ForVersion(v);
	if (vn == 12 && std::strncmp(v, "SteamParties", 12) == 0) return SteamParties_ForVersion(v);
	if (vn == 11 && std::strncmp(v, "SteamClient", 11) == 0) return SteamClient_ForVersion(v);
	if (vn == 10 && std::strncmp(v, "SteamInput", 10) == 0) return SteamInput_ForVersion(v);
	if (vn == 10 && std::strncmp(v, "SteamUtils", 10) == 0) return SteamUtils_ForVersion(v);
	if (vn == 9 && std::strncmp(v, "SteamUser", 9) == 0) return SteamUser_ForVersion(v);
	return nullptr;
}

void* FindInterfaceGS(const char* v) {
	if (!v) return nullptr;
	size_t vn = IfaceStemLen(v);
	if (vn == 23 && std::strncmp(v, "SteamNetworkingMessages", 23) == 0) return SteamNetworkingMessages_ForVersionGS(v);
	if (vn == 22 && std::strncmp(v, "SteamNetworkingSockets", 22) == 0) return SteamNetworkingSockets_ForVersionGS(v);
	if (vn == 15 && std::strncmp(v, "SteamNetworking", 15) == 0) return SteamNetworking_ForVersionGS(v);
	return FindInterface(v);
}

void* FlatNormalize(void* self) {
	if (!self) return self;
	struct Range { uintptr_t base; size_t size; void* primary; };
	static const Range k[] = {
		{ (uintptr_t)static_cast<CClient*>(SteamClient_()), sizeof(CClient), (void*)SteamClient_() },
		{ (uintptr_t)static_cast<CUser*>(SteamUser_()), sizeof(CUser), (void*)SteamUser_() },
		{ (uintptr_t)static_cast<CFriends*>(SteamFriends_()), sizeof(CFriends), (void*)SteamFriends_() },
		{ (uintptr_t)static_cast<CUtils*>(SteamUtils_()), sizeof(CUtils), (void*)SteamUtils_() },
		{ (uintptr_t)static_cast<CMatchmaking*>(SteamMatchmaking_()), sizeof(CMatchmaking), (void*)SteamMatchmaking_() },
		{ (uintptr_t)static_cast<CMatchmakingServers*>(SteamMatchmakingServers_()), sizeof(CMatchmakingServers), (void*)SteamMatchmakingServers_() },
		{ (uintptr_t)static_cast<CParties*>(SteamParties_()), sizeof(CParties), (void*)SteamParties_() },
		{ (uintptr_t)static_cast<CRemoteStorage*>(SteamRemoteStorage_()), sizeof(CRemoteStorage), (void*)SteamRemoteStorage_() },
		{ (uintptr_t)static_cast<CUserStats*>(SteamUserStats_()), sizeof(CUserStats), (void*)SteamUserStats_() },
		{ (uintptr_t)static_cast<CApps*>(SteamApps_()), sizeof(CApps), (void*)SteamApps_() },
		{ (uintptr_t)static_cast<CNetworking*>(SteamNetworking_()), sizeof(CNetworking), (void*)SteamNetworking_() },
		{ (uintptr_t)static_cast<CScreenshots*>(SteamScreenshots_()), sizeof(CScreenshots), (void*)SteamScreenshots_() },
		{ (uintptr_t)static_cast<CMusic*>(SteamMusic_()), sizeof(CMusic), (void*)SteamMusic_() },
		{ (uintptr_t)static_cast<CHTTP*>(SteamHTTP_()), sizeof(CHTTP), (void*)SteamHTTP_() },
		{ (uintptr_t)static_cast<CInput*>(SteamInput_()), sizeof(CInput), (void*)SteamInput_() },
		{ (uintptr_t)static_cast<CController*>(SteamController_()), sizeof(CController), (void*)SteamController_() },
		{ (uintptr_t)static_cast<CUGC*>(SteamUGC_()), sizeof(CUGC), (void*)SteamUGC_() },
		{ (uintptr_t)static_cast<CHTMLSurface*>(SteamHTMLSurface_()), sizeof(CHTMLSurface), (void*)SteamHTMLSurface_() },
		{ (uintptr_t)static_cast<CInventory*>(SteamInventory_()), sizeof(CInventory), (void*)SteamInventory_() },
		{ (uintptr_t)static_cast<CTimeline*>(SteamTimeline_()), sizeof(CTimeline), (void*)SteamTimeline_() },
		{ (uintptr_t)static_cast<CVideo*>(SteamVideo_()), sizeof(CVideo), (void*)SteamVideo_() },
		{ (uintptr_t)static_cast<CParentalSettings*>(SteamParentalSettings_()), sizeof(CParentalSettings), (void*)SteamParentalSettings_() },
		{ (uintptr_t)static_cast<CRemotePlay*>(SteamRemotePlay_()), sizeof(CRemotePlay), (void*)SteamRemotePlay_() },
		{ (uintptr_t)static_cast<CNetworkingMessages*>(SteamNetworkingMessages_()), sizeof(CNetworkingMessages), (void*)SteamNetworkingMessages_() },
		{ (uintptr_t)static_cast<CNetworkingSockets*>(SteamNetworkingSockets_()), sizeof(CNetworkingSockets), (void*)SteamNetworkingSockets_() },
		{ (uintptr_t)static_cast<CNetworkingUtils*>(SteamNetworkingUtils_()), sizeof(CNetworkingUtils), (void*)SteamNetworkingUtils_() },
		{ (uintptr_t)static_cast<CGameServer*>(SteamGameServer_()), sizeof(CGameServer), (void*)SteamGameServer_() },
		{ (uintptr_t)static_cast<CGameServerStats*>(SteamGameServerStats_()), sizeof(CGameServerStats), (void*)SteamGameServerStats_() },
		{ (uintptr_t)static_cast<CNetworking*>(SteamNetworkingGS_()), sizeof(CNetworking), (void*)SteamNetworkingGS_() },
		{ (uintptr_t)static_cast<CNetworkingSockets*>(SteamNetworkingSocketsGS_()), sizeof(CNetworkingSockets), (void*)SteamNetworkingSocketsGS_() },
		{ (uintptr_t)static_cast<CNetworkingMessages*>(SteamNetworkingMessagesGS_()), sizeof(CNetworkingMessages), (void*)SteamNetworkingMessagesGS_() },
	};
	const uintptr_t s = (uintptr_t)self;
	for (const auto& e : k)
		if (s >= e.base && s - e.base < e.size) return e.primary;
	return self;
}

